function esc(v){return String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
async function api(url,opt={}){const h={'Content-Type':'application/json',...(opt.headers||{})};if(token)h.Authorization='Bearer '+token;const r=await fetch(url,{...opt,headers:h});let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.error||'Request failed');return j}
function toast(msg){const x=document.createElement('div');x.className='toast';x.textContent=msg;document.body.appendChild(x);setTimeout(()=>x.remove(),2600)}
function lessonId(w,d){return `w${w}d${d}`}
function weekDone(w){return Array.from({length:7},(_,i)=>lessonId(w,i+1)).every(id=>state.progress.completed.includes(id))}
function weekUnlocked(w){if(w<=state.placement.startingWeek)return true;return weekDone(w-1)||Number(state.progress.weeklyMastery[w-1]||0)>=70}
function completion(){return Math.round((state.progress.completed.length/168)*100)}
function dueCards(){const now=Date.now();return Object.entries(state.vocab||{}).filter(([,v])=>!v.due||v.due<=now).sort((a,b)=>(a[1].due||0)-(b[1].due||0))}
function nextLesson(){let w=Math.max(1,state.profile.currentWeek||1),d=Math.max(1,state.profile.currentDay||1);for(let i=0;i<168;i++){const id=lessonId(w,d);if(!state.progress.completed.includes(id)&&weekUnlocked(w))return {w,d};d++;if(d>7){d=1;w++;if(w>24)break}}return {w:24,d:7}}
async function save(){await api('/api/state',{method:'PUT',body:JSON.stringify({state})})}
function authScreen(){return `<div class="auth-wrap"><section class="auth-art"><div><div class="brand"><div class="brand-mark">B</div><div class="brand-copy"><strong>Beheshti Academy</strong><span>Learn English. Build Your Future.</span></div></div><h1>English that produces evidence, not empty progress.</h1><p>24 weeks, 168 structured study days, real accounts and persistent progress. Listening, vocabulary, grammar, reading, speaking evidence, writing evidence and mastery gates are stored in a real database.</p><div class="auth-points"><div class="auth-point"><strong>Real progression</strong><span>Mastery gates control advancement.</span></div><div class="auth-point"><strong>Real persistence</strong><span>Your work survives devices and sessions.</span></div><div class="auth-point"><strong>Honest assessment</strong><span>No fake AI fluency or pronunciation scores.</span></div></div></div><div class="small">Production architecture · PostgreSQL · authenticated learner records</div></section><section class="auth-panel"><div class="auth-card"><div class="brand" style="color:var(--ink);margin-bottom:22px"><div class="brand-mark" style="background:var(--brand);color:white">B</div><div class="brand-copy"><strong>Beheshti Academy</strong><span style="color:var(--muted)">English learning system</span></div></div><div class="tabs"><button data-auth="login" class="${authMode==='login'?'active':''}">Sign in</button><button data-auth="register" class="${authMode==='register'?'active':''}">Create account</button></div>${authMode==='login'?`<form id="loginForm" class="stack"><div class="field"><label>Email</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn btn-primary" type="submit">Sign in</button></form>`:`<form id="registerForm" class="stack"><div class="field"><label>Name</label><input name="name" required autocomplete="name"></div><div class="field"><label>Email</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required autocomplete="new-password"></div><button class="btn btn-primary" type="submit">Create account</button></form>`}<p class="footer-note">This version does not invent AI feedback. Speaking is stored as transcript/evidence where browser speech recognition is available; writing is stored as learner evidence.</p></div></section></div>`}
function onboarding(){if(!state.profile.setupComplete&&!state.placement.completed)return `<div class="auth-panel" style="min-height:100vh"><div class="card" style="width:min(760px,100%)"><span class="pill">Step 1 of 2</span><h2 style="font-size:32px;margin-bottom:8px">Build your study plan</h2><p class="small">Your plan controls scheduling; it does not pretend to be AI adaptation.</p><form id="setupForm" class="grid grid-2" style="margin-top:22px"><div class="field"><label>Learning goal</label><select name="goal"><option>General English</option><option>Professional English</option><option>Academic English</option><option>Travel & Daily Life</option></select></div><div class="field"><label>Daily study time</label><select name="minutes"><option value="30">30 minutes</option><option value="45" selected>45 minutes</option><option value="60">60 minutes</option><option value="90">90 minutes</option></select></div><div class="field"><label>Preferred reference accent</label><select name="accent"><option>American</option><option>British</option></select></div><div class="field"><label>Dari support</label><select name="dari"><option value="yes">On</option><option value="no">Off</option></select></div><div style="grid-column:1/-1"><button class="btn btn-primary" type="submit">Continue to placement</button></div></form></div></div>`;return placementScreen()}
function placementScreen(){const i=placementIndex,q=PL[i];if(i>=PL.length)return `<div class="auth-panel" style="min-height:100vh"><div class="card" style="width:min(680px,100%);text-align:center"><span class="pill">Placement complete</span><h2>Your provisional score: ${placementScore}/${PL.length}</h2><p class="small">This is a routing test, not a certified CEFR exam. It chooses a sensible starting point; mastery gates still control progression.</p><button class="btn btn-primary" data-action="finish-placement">Start my program</button></div></div>`;return `<div class="auth-panel" style="min-height:100vh"><div class="card" style="width:min(680px,100%)"><div class="row space"><span class="pill">Placement</span><span class="small">${i+1} / ${PL.length}</span></div><div style="height:7px;background:#e6ebe7;border-radius:99px;margin:16px 0 28px"><div style="width:${((i)/PL.length)*100}%;height:100%;background:var(--brand);border-radius:99px"></div></div><h2>${esc(q[0])}</h2><div class="stack" style="margin-top:20px">${q[1].map((o,n)=>`<button class="option" data-placement="${n}"><strong>${String.fromCharCode(65+n)}.</strong><span>${esc(o)}</span></button>`).join('')}</div></div></div>`}
function shell(content,title='Beheshti Academy',sub='Learn English. Build Your Future.'){const initial=esc((user?.name||'L').slice(0,1).toUpperCase());return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">B</div><div class="brand-copy"><strong>Beheshti Academy</strong><span>Learn English. Build Your Future.</span></div></div><nav class="nav">${[['dashboard','Dashboard'],['course','Course map'],['review','Smart review'],['evidence','Evidence'],['profile','Profile']].map(([v,n])=>`<button data-nav="${v}" class="${view===v?'active':''}">${n}</button>`).join('')}</nav><div class="sidebar-foot">24 weeks · 168 study days<br>English-first with optional Dari support.<br><br>No synthetic proficiency scores.</div></aside><main class="main"><header class="topbar"><div class="topbar-left"><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="row"><button class="btn btn-ghost mobile-menu" data-action="mobile-nav">Menu</button><div class="user-chip"><div class="avatar">${initial}</div><span class="name small">${esc(user?.name||'Learner')}</span></div></div></header><div class="content">${content}</div></main></div>`}
function dashboard(){const n=nextLesson(),wk=C[n.w-1],pct=completion(),due=dueCards().length;return shell(`<section class="hero"><div class="card hero-main"><div class="eyebrow">Your next verified step</div><h2>Week ${n.w}: ${esc(wk.t)}</h2><p>${esc(wk.o)}</p><div class="row" style="margin-top:22px"><button class="btn" style="background:white;color:var(--brand)" data-open-lesson="${n.w},${n.d}">Continue · Day ${n.d} ${DAYS[n.d-1]}</button><span class="pill" style="background:rgba(255,255,255,.12);color:#fff">${esc(wk.l)}</span></div></div><div class="card hero-side"><div><div class="small">Program completion</div><div class="progress-ring" style="--p:${pct};margin-top:14px"><strong>${pct}%</strong></div></div><div class="small" style="text-align:center">${state.progress.completed.length} of 168 study days completed</div></div></section><section class="grid grid-4" style="margin-top:18px"><div class="card metric"><div class="metric-label">Current streak</div><div class="metric-value">${state.progress.streak||0}</div><div class="metric-sub">study days</div></div><div class="card metric"><div class="metric-label">Vocabulary due</div><div class="metric-value">${due}</div><div class="metric-sub">spaced review cards</div></div><div class="card metric"><div class="metric-label">Current level</div><div class="metric-value">${esc(C[Math.max(0,(state.profile.currentWeek||1)-1)].l)}</div><div class="metric-sub">program band, not certification</div></div><div class="card metric"><div class="metric-label">Evidence saved</div><div class="metric-value">${state.artifacts?.length||0}</div><div class="metric-sub">speaking / writing artifacts</div></div></section><section class="grid grid-2" style="margin-top:18px"><div class="card"><div class="row space"><div><h3>Today’s plan</h3><div class="small">${state.profile.dailyMinutes} minutes · ${esc(state.profile.goal)}</div></div><span class="pill">Day ${n.d}</span></div><div class="divider"></div><div class="profile-list"><div class="profile-item"><span>Core activity</span><strong>${DAYS[n.d-1]}</strong></div><div class="profile-item"><span>Grammar focus</span><strong style="text-align:right;max-width:55%">${esc(wk.g)}</strong></div><div class="profile-item"><span>Review due</span><strong>${due} cards</strong></div></div></div><div class="card"><h3>Integrity rules</h3><p class="small" style="line-height:1.8">Speaking completion requires captured speech evidence where the browser supports recognition. Writing completion stores the learner’s actual text. Mastery uses activity scores and does not award a fabricated AI pronunciation or fluency grade.</p><button class="btn btn-secondary" data-nav="course">Open course map</button></div></section>`,'Dashboard','Your persisted learning record')}
function course(){return shell(`<div class="curriculum-header"><span class="pill">24-week pathway</span><h2 style="font-size:30px;margin-bottom:8px">Course map</h2><p>Each week has seven real study days: Teach, Listening, Vocabulary, Grammar, Reading, Speaking and Mastery. Locked weeks open through verified completion/mastery—not decorative progress.</p></div><div class="week-grid">${C.map((w,i)=>{const n=i+1,un=weekUnlocked(n),done=weekDone(n),cur=n===state.profile.currentWeek;return `<article class="week-card ${!un?'locked':''} ${cur?'current':''}"><div class="row space"><span class="week-no">Week ${n}</span><span class="pill ${done?'':'gold'}">${done?'Complete':esc(w.l)}</span></div><h3>${esc(w.t)}</h3><p>${esc(w.o)}</p><div class="small">${esc(w.g)}</div><div style="margin-top:14px"><button class="btn ${un?'btn-secondary':'btn-ghost'}" ${!un?'disabled':''} data-open-lesson="${n},1">${done?'Review week':un?'Open week':'Locked'}</button></div></article>`}).join('')}</div>`,'Course map','A structured A1–B2 six-month pathway')}
function weekTrack(w,d){return `<div class="day-track">${DAYS.map((n,i)=>{const id=lessonId(w,i+1);return `<div class="day-node ${state.progress.completed.includes(id)?'done':''} ${d===i+1?'current':''}">${i+1}<br>${n}</div>`}).join('')}</div>`}
function currentBlock(w,d){const wk=C[w-1],id=lessonId(w,d);if(d===1)return `<div class="lesson-block"><h3>Outcome</h3><p>${esc(wk.o)}</p></div><div class="lesson-block"><h3>Language focus</h3><p><strong>${esc(wk.g)}</strong></p><p>${esc(wk.e)}</p>${state.settings.dariSupport?`<div class="dari-note">${esc(wk.h)}</div>`:''}</div><div class="lesson-block"><h3>Quick evidence check</h3>${mcq(id,'teach',wk.q)}</div>`;
if(d===2)return `<div class="lesson-block"><h3>Listening & dictation</h3><p>Play the passage, listen without looking, then type what you heard. Browser speech synthesis is used as an audible practice source; it is not presented as a human recording.</p><div class="row"><button class="btn btn-secondary" data-speak="${esc(wk.e)}">Play passage</button><button class="btn btn-ghost" data-action="stop-audio">Stop</button></div><form id="dictationForm" class="stack" style="margin-top:16px"><div class="field"><label>Your dictation</label><textarea name="text" required placeholder="Type what you hear..."></textarea></div><button class="btn btn-primary">Check dictation</button></form></div>`;
if(d===3)return `<div class="lesson-block"><h3>Vocabulary lab</h3><p>Save these words to spaced review. Definitions are retrieved through the academy backend and cached when available.</p><div class="vocab-list">${wk.w.map(x=>`<div class="vocab"><strong>${esc(x)}</strong><span class="dict-result" id="dict-${esc(x)}">Week ${w} focus word</span><div class="row" style="margin-top:8px"><button class="btn btn-ghost" data-dict="${esc(x)}">Definition</button><button class="btn btn-secondary" data-card="${esc(x)}">Add to review</button></div></div>`).join('')}</div><div style="margin-top:16px"><button class="btn btn-primary" data-complete-simple="85">Complete vocabulary setup</button></div></div>`;
if(d===4)return `<div class="lesson-block"><h3>Grammar check</h3><p><strong>${esc(wk.g)}</strong></p>${mcq(id,'grammar',wk.q)}</div>`;
if(d===5)return `<div class="lesson-block"><h3>Reading</h3><p>${esc(wk.r)}</p><div class="divider"></div>${mcq(id,'reading',wk.rq)}</div>`;
if(d===6)return `<div class="lesson-block"><h3>Speaking evidence</h3><p><strong>Prompt:</strong> ${esc(wk.s)}</p><div class="mic-box"><div class="row"><button class="btn btn-primary" data-action="start-mic">Start microphone</button><span class="small">Uses browser speech recognition when supported.</span></div><div id="transcript" class="transcript">Your captured transcript will appear here.</div></div><form id="speakingForm" class="stack" style="margin-top:14px"><input type="hidden" name="transcript" id="speechValue"><div class="field"><label>Optional self-reflection</label><textarea name="reflection" placeholder="What was difficult? What did you repair?"></textarea></div><button class="btn btn-primary">Save speaking evidence & complete</button></form></div>`;
const scores=[1,2,4,5].map(x=>Number(state.progress.scores[lessonId(w,x)]||0)).filter(Boolean);const avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;return `<div class="lesson-block"><h3>Mastery gate</h3><p>This gate uses your scored Teach, Listening, Grammar and Reading activities. Speaking/writing evidence is not given a fake automated fluency score.</p><div class="score-box"><div class="metric-label">Current scored-activity average</div><div class="metric-value">${avg}%</div><div class="metric-sub">Threshold to unlock the next week: 70%</div></div><div style="margin-top:16px">${avg>=70?`<button class="btn btn-primary" data-master="${avg}">Pass mastery & unlock next week</button>`:`<div class="alert">You need at least 70%. Revisit weak scored activities before completing mastery.</div>`}</div></div>`}
function mcq(id,activity,q){return `<div class="stack">${q[1].map((o,i)=>`<button class="option" data-mcq="${id}|${activity}|${i}|${q[2]}"><strong>${String.fromCharCode(65+i)}.</strong><span>${esc(o)}</span></button>`).join('')}</div>`}
function lesson(){const [w,d]=lessonRef||[state.profile.currentWeek,state.profile.currentDay],wk=C[w-1],id=lessonId(w,d);return shell(`<div class="lesson-head"><div><span class="pill">Week ${w} · ${esc(wk.l)}</span><h2>${esc(wk.t)}</h2><div class="small">Day ${d}: ${DAYS[d-1]} · ${esc(wk.o)}</div></div><div class="row"><button class="btn btn-ghost" data-nav="course">Course map</button>${d>1?`<button class="btn btn-ghost" data-open-lesson="${w},${d-1}">Previous</button>`:''}${d<7?`<button class="btn btn-ghost" data-open-lesson="${w},${d+1}">Next</button>`:''}</div></div>${weekTrack(w,d)}<div class="lesson-layout" style="margin-top:18px"><section class="lesson-main">${currentBlock(w,d)}${d===6?`<div class="lesson-block"><h3>Writing evidence</h3><p>${esc(wk.x)}</p><form id="writingForm" class="stack"><div class="field"><label>Your writing</label><textarea name="content" required minlength="40"></textarea></div><button class="btn btn-secondary">Save writing evidence</button></form></div>`:''}</section><aside class="card lesson-side"><div class="small">Lesson record</div><div class="profile-list" style="margin-top:8px"><div class="profile-item"><span>ID</span><strong>${id}</strong></div><div class="profile-item"><span>Status</span><strong>${state.progress.completed.includes(id)?'Complete':'Open'}</strong></div><div class="profile-item"><span>Score</span><strong>${state.progress.scores[id]!=null?state.progress.scores[id]+'%':'—'}</strong></div></div><div class="divider"></div><div class="small">Dari support explains transfer risks; it does not replace English practice.</div></aside></div>`,'Lesson',`Week ${w} · Day ${d}`)}
function review(){const due=dueCards();return shell(`<div class="row space"><div><span class="pill">Spaced repetition</span><h2>Smart review</h2><p class="small">Cards become due based on your previous recall rating.</p></div><strong>${due.length} due</strong></div><div class="grid grid-2" style="margin-top:18px">${due.length?due.slice(0,20).map(([word,v])=>`<div class="card"><div class="row space"><h3>${esc(word)}</h3><span class="pill">Box ${v.box||1}</span></div><p class="small">Last result: ${esc(v.last||'new')}</p><div class="row"><button class="btn btn-danger" data-review="${esc(word)}|again">Again</button><button class="btn btn-ghost" data-review="${esc(word)}|hard">Hard</button><button class="btn btn-secondary" data-review="${esc(word)}|good">Good</button><button class="btn btn-primary" data-review="${esc(word)}|easy">Easy</button></div></div>`).join(''):`<div class="card empty">No cards are due right now. Add focus words from Vocabulary days.</div>`}</div>`,'Smart review','Spaced retrieval based on your recall')}
function evidence(){const a=[...(state.artifacts||[])].reverse();return shell(`<div class="row space"><div><span class="pill">Learner evidence</span><h2>Speaking & writing record</h2><p class="small">These are your actual artifacts. They are evidence, not synthetic proficiency scores.</p></div><button class="btn btn-ghost" data-action="refresh-evidence">Refresh from database</button></div><div class="stack" style="margin-top:18px">${a.length?a.map(x=>`<article class="card"><div class="row space"><div><span class="pill">${esc(x.type)}</span><strong style="margin-left:8px">${esc(x.lessonId||x.lesson_id)}</strong></div><span class="small">${esc((x.createdAt||x.created_at||'').toString().slice(0,10))}</span></div><p style="white-space:pre-wrap;line-height:1.7">${esc(x.content)}</p></article>`).join(''):`<div class="card empty">No evidence saved yet.</div>`}</div>`,'Evidence','Stored work that you can inspect')}
function profile(){return shell(`<div class="grid grid-2"><div class="card"><h2>${esc(user.name)}</h2><div class="small">${esc(user.email)}</div><div class="divider"></div><div class="profile-list"><div class="profile-item"><span>Goal</span><strong>${esc(state.profile.goal)}</strong></div><div class="profile-item"><span>Daily plan</span><strong>${state.profile.dailyMinutes} min</strong></div><div class="profile-item"><span>Reference accent</span><strong>${esc(state.profile.accent)}</strong></div><div class="profile-item"><span>Placement</span><strong>${esc(state.placement.provisionalLevel||'—')}</strong></div><div class="profile-item"><span>Starting week</span><strong>${state.placement.startingWeek}</strong></div></div></div><div class="card"><h3>Account controls</h3><p class="small">Your learning state is stored server-side in PostgreSQL. Logging out removes only the local session token.</p><div class="stack"><button class="btn btn-ghost" data-action="export-state">Export my state</button><button class="btn btn-danger" data-action="logout">Log out</button></div></div></div>`,'Profile','Account and learning settings')}
function render(){if(!token||!user||!state){app.innerHTML=authScreen();return}if(!state.profile.setupComplete){app.innerHTML=onboarding();return}if(view==='dashboard')app.innerHTML=dashboard();else if(view==='course')app.innerHTML=course();else if(view==='lesson')app.innerHTML=lesson();else if(view==='review')app.innerHTML=review();else if(view==='evidence')app.innerHTML=evidence();else app.innerHTML=profile()}
async function complete(w,d,score=null){const id=lessonId(w,d);if(!state.progress.completed.includes(id))state.progress.completed.push(id);if(score!=null)state.progress.scores[id]=Math.max(0,Math.min(100,Math.round(score)));const today=new Date().toISOString().slice(0,10),last=state.progress.lastStudyDate;if(last!==today){const y=new Date(Date.now()-86400000).toISOString().slice(0,10);state.progress.streak=last===y?(state.progress.streak||0)+1:1;state.progress.lastStudyDate=today}if(d<7){state.profile.currentWeek=w;state.profile.currentDay=d+1}else if(w<24){state.profile.currentWeek=w+1;state.profile.currentDay=1}await save();await api('/api/events',{method:'POST',body:JSON.stringify({lessonId:id,activity:DAYS[d-1],score})});toast('Progress saved');render()}
function similarity(a,b){const n=s=>s.toLowerCase().replace(/[^a-z0-9' ]/g,' ').split(/\s+/).filter(Boolean),A=n(a),B=n(b);if(!B.length)return 0;let m=0,used=new Set();A.forEach(x=>{const i=B.findIndex((y,j)=>y===x&&!used.has(j));if(i>=0){used.add(i);m++}});return Math.round((2*m/(A.length+B.length))*100)||0}
async function boot(){if(!token){render();return}try{const [m,s]=await Promise.all([api('/api/me'),api('/api/state')]);user=m.user;state=s.state;render()}catch(e){localStorage.removeItem(KEY);token='';user=null;state=null;render()}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
if(b.dataset.auth){authMode=b.dataset.auth;render();return}
if(b.dataset.nav){view=b.dataset.nav;render();return}
if(b.dataset.openLesson){const [w,d]=b.dataset.openLesson.split(',').map(Number);if(!weekUnlocked(w)){toast('Complete the previous mastery gate first.');return}lessonRef=[w,d];view='lesson';render();return}
if(b.dataset.placement!=null){const ans=Number(b.dataset.placement),q=PL[placementIndex];placementAnswers.push(ans);if(ans===q[2])placementScore++;placementIndex++;render();return}
if(b.dataset.speak!=null){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(b.dataset.speak);u.lang=state.profile.accent==='British'?'en-GB':'en-US';u.rate=.88;speechSynthesis.speak(u);return}
if(b.dataset.dict){const j=await api('/api/dictionary',{method:'POST',body:JSON.stringify({term:b.dataset.dict})});const el=document.getElementById('dict-'+b.dataset.dict);if(el)el.textContent=[j.entry.phonetic,j.entry.partOfSpeech,j.entry.definition].filter(Boolean).join(' · ');return}
if(b.dataset.card){const word=b.dataset.card;state.vocab[word]={box:1,due:Date.now(),last:'new'};await save();toast(`${word} added to review`);return}
if(b.dataset.mcq){const [id,activity,choice,correct]=b.dataset.mcq.split('|');const [w,d]=[Number(id.match(/^w(\d+)/)[1]),Number(id.match(/d(\d+)$/)[1])];const ok=Number(choice)===Number(correct);b.parentElement.querySelectorAll('.option').forEach(x=>x.disabled=true);b.classList.add(ok?'correct':'wrong');if(!ok)b.parentElement.querySelectorAll('.option')[Number(correct)]?.classList.add('correct');setTimeout(()=>complete(w,d,ok?100:55),550);return}
if(b.dataset.completeSimple){const [w,d]=lessonRef;await complete(w,d,Number(b.dataset.completeSimple));return}
if(b.dataset.master){const [w,d]=lessonRef;state.progress.weeklyMastery[w]=Number(b.dataset.master);await complete(w,d,Number(b.dataset.master));return}
if(b.dataset.review){const [word,rating]=b.dataset.review.split('|'),v=state.vocab[word]||{box:1};const days={again:0.02,hard:1,good:3,easy:7}[rating];v.box=rating==='again'?1:Math.min(8,(v.box||1)+(rating==='easy'?2:1));v.last=rating;v.due=Date.now()+days*86400000;state.vocab[word]=v;await save();render();return}
if(b.dataset.action==='stop-audio'){speechSynthesis.cancel();return}
if(b.dataset.action==='start-mic'){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Speech recognition is not supported in this browser. You can type your transcript manually in the reflection field and save writing evidence instead.');return}const r=new SR();r.lang=state.profile.accent==='British'?'en-GB':'en-US';r.interimResults=true;r.continuous=false;const t=document.getElementById('transcript'),v=document.getElementById('speechValue');r.onresult=ev=>{let x='';for(let i=ev.resultIndex;i<ev.results.length;i++)x+=ev.results[i][0].transcript+' ';t.textContent=x.trim();v.value=x.trim()};r.onerror=()=>toast('Microphone recognition failed. Check browser permission.');r.start();return}
if(b.dataset.action==='logout'){localStorage.removeItem(KEY);token='';user=null;state=null;view='dashboard';render();return}
if(b.dataset.action==='export-state'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='beheshti-academy-state.json';a.click();URL.revokeObjectURL(a.href);return}
if(b.dataset.action==='refresh-evidence'){const j=await api('/api/artifacts');state.artifacts=j.artifacts;await save();render();return}
if(b.dataset.action==='finish-placement'){const s=placementScore;let start=1,level='A1';if(s>=14){start=17;level='B1+/B2'}else if(s>=11){start=13;level='B1'}else if(s>=8){start=9;level='A2'}else if(s>=5){start=5;level='A1+'}state.placement={completed:true,score:s,provisionalLevel:level,startingWeek:start,answers:placementAnswers};state.profile.currentWeek=start;state.profile.currentDay=1;state.profile.setupComplete=true;await save();view='dashboard';toast('Placement saved');render();return}
}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f);try{
if(f.id==='loginForm'){const j=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:fd.get('email'),password:fd.get('password')})});token=j.token;localStorage.setItem(KEY,token);user=j.user;state=j.state;render();return}
if(f.id==='registerForm'){const j=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:fd.get('name'),email:fd.get('email'),password:fd.get('password')})});token=j.token;localStorage.setItem(KEY,token);user=j.user;state=j.state;render();return}
if(f.id==='setupForm'){state.profile.goal=fd.get('goal');state.profile.dailyMinutes=Number(fd.get('minutes'));state.profile.accent=fd.get('accent');state.settings.dariSupport=fd.get('dari')==='yes';state.placement.completed=false;await save();placementIndex=0;placementScore=0;placementAnswers=[];render();return}
if(f.id==='dictationForm'){const [w,d]=lessonRef,wk=C[w-1],score=similarity(fd.get('text'),wk.e);toast(`Dictation similarity: ${score}%`);await complete(w,d,score);return}
if(f.id==='speakingForm'){const [w,d]=lessonRef,trans=String(fd.get('transcript')||'').trim(),reflection=String(fd.get('reflection')||'').trim();if(!trans){toast('Capture speech first. No fake speaking completion without evidence.');return}const content=trans+(reflection?`\n\nSelf-reflection: ${reflection}`:'');const j=await api('/api/artifacts',{method:'POST',body:JSON.stringify({lessonId:lessonId(w,d),type:'speaking',content,meta:{prompt:C[w-1].s}})});state.artifacts.push(j.artifact);await complete(w,d,null);return}
if(f.id==='writingForm'){const [w,d]=lessonRef,content=String(fd.get('content')||'').trim();const j=await api('/api/artifacts',{method:'POST',body:JSON.stringify({lessonId:lessonId(w,d),type:'writing',content,meta:{prompt:C[w-1].x}})});state.artifacts.push(j.artifact);await save();toast('Writing evidence saved');render();return}
}catch(err){toast(err.message)}});
boot();
